package com.chance.bitlifediag;
import android.app.*;import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
/** Preset library, scoped activation and a transactional local editor. */
public final class NamePackUI {
 public static final int IMPORT=1301,EXPORT=1302;
 private final Activity activity;private LinearLayout body;private String exportDocument;private PackWorkspace42 workspace;private String presetQuery="",category="All";private boolean favoritesOnly;
 private final Set<String> favorites=new HashSet<>();
 public NamePackUI(Activity a){activity=a;favorites.addAll(a.getSharedPreferences("mayo_packs42",0).getStringSet("favorites",Collections.<String>emptySet()));}
 public void save(android.os.Bundle b){b.putString("namepack_export",exportDocument);b.putString("pack_query",presetQuery);b.putString("pack_category",category);b.putBoolean("pack_favorites",favoritesOnly);try{if(workspace!=null)b.putString("pack_editing",workspace.pack().document);}catch(Exception ignored){}}
 public void restore(android.os.Bundle b){exportDocument=b.getString("namepack_export");presetQuery=b.getString("pack_query","");category=b.getString("pack_category","All");favoritesOnly=b.getBoolean("pack_favorites",false);try{String s=b.getString("pack_editing");if(s!=null)workspace=new PackWorkspace42(PackFormat.parse(s));}catch(Exception ignored){}}
 private File directory(){File f=new File(activity.getFilesDir(),"namepacks");f.mkdirs();return f;}private File active(){return new File(activity.getFilesDir(),"namepack-active.bin");}
 private String read(File f)throws Exception{try(InputStream in=new FileInputStream(f)){return PackFormat.utf8(PackFormat.read(in));}}
 private void write(File f,String s)throws Exception{File n=new File(f.getPath()+".new");try(FileOutputStream out=new FileOutputStream(n)){out.write(s.getBytes("UTF-8"));out.getFD().sync();}if(!n.renameTo(f))throw new IOException("Could not save. Previous file retained.");}
 private void error(Exception e){new AlertDialog.Builder(activity).setTitle("Pack unavailable").setMessage(e.getMessage()).setPositiveButton("OK",null).show();}
 private void page(String title){ScrollView scroll=new ScrollView(activity);scroll.setFillViewport(true);scroll.setBackgroundColor(ToolStyle41.BG);scroll.setVerticalScrollBarEnabled(false);scroll.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i.consumeSystemWindowInsets();});body=ToolStyle41.column(activity);int side=Math.max(16,Math.round((activity.getResources().getDisplayMetrics().widthPixels/activity.getResources().getDisplayMetrics().density-600)/2));body.setPadding(ToolStyle41.dp(activity,side),ToolStyle41.dp(activity,16),ToolStyle41.dp(activity,side),ToolStyle41.dp(activity,24));scroll.addView(body);label(title,25);activity.setContentView(scroll);scroll.requestApplyInsets();ToolStyle41.enter(body);}
 private void label(String s,int size){TextView t=ToolStyle41.text(activity,s,size,size>=23?ToolStyle41.TEXT:ToolStyle41.MUTED);t.setPadding(0,ToolStyle41.dp(activity,8),0,ToolStyle41.dp(activity,10));body.addView(t);}
 private void button(String s,Runnable r){String l=s.toLowerCase(Locale.ROOT);Button b=ToolStyle41.button(activity,body,s,l.startsWith("back")?"back":l.contains("search")?"search":l.contains("save")||l.contains("import")||l.contains("export")?"save":l.contains("undo")||l.contains("restore")?"refresh":l.contains("duplicate")?"copy":l.contains("apply")?"play":"gift",r);String k=l.contains("favorite")?"star":l.contains("delete")?"trash":l.contains("create")?"plus":l.contains("customize")||l.startsWith("edit")||l.contains("bulk")?"edit":null;if(k!=null)setGlyph(b,k,0xff8bafff);if(l.startsWith("apply")||l.startsWith("save bulk"))ToolStyle41.surface(b,0xff15384c);}
 private void setGlyph(Button b,String kind,int color){PackGlyph42 icon=new PackGlyph42(kind,color);int n=ToolStyle41.dp(activity,24);icon.setBounds(0,0,n,n);b.setCompoundDrawables(icon,null,null,null);}
 private void themeButton(String title,String category,Runnable action){Button b=ToolStyle41.button(activity,body,title,"gift",action);setGlyph(b,category,PackGlyph42.accent(category));b.setTextSize(16);b.setPadding(ToolStyle41.dp(activity,16),ToolStyle41.dp(activity,18),ToolStyle41.dp(activity,16),ToolStyle41.dp(activity,18));}
 private EditText input(String s,String hint){EditText e=new EditText(activity);e.setSingleLine();e.setTextColor(ToolStyle41.TEXT);e.setHintTextColor(ToolStyle41.MUTED);e.setText(s);e.setHint(hint);e.setBackground(ToolStyle41.shape(activity,ToolStyle41.CARD));int p=ToolStyle41.dp(activity,14);e.setPadding(p,p,p,p);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=ToolStyle41.dp(activity,8);body.addView(e,lp);return e;}
 private Spinner select(String heading,List<String> values){label(heading,14);Spinner s=new Spinner(activity);ArrayAdapter<String>a=new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,values);s.setAdapter(a);s.setBackground(ToolStyle41.shape(activity,0xffe1e9f7));body.addView(s,new LinearLayout.LayoutParams(-1,ToolStyle41.dp(activity,48)));return s;}
 private CheckBox check(String s,boolean value){CheckBox c=new CheckBox(activity);c.setText(s);c.setTextColor(ToolStyle41.TEXT);c.setChecked(value);c.setMinHeight(ToolStyle41.dp(activity,48));body.addView(c);return c;}
 private PackFormat.Pack currentActive(){try{return PackFormat.parse(read(new File(directory(),"active.json")));}catch(Exception e){return null;}}
 public void show(){
  page("Name packs");PackFormat.Pack activePack=currentActive();
  ToolStyle41.status(activity,body,"ACTIVE COLLECTION",activePack==null?"Original team names":activePack.name(),activePack==null?"Real team identities are ready to play.":activePack.count()+" names applied on this device.");
  ToolStyle41.pair(activity,body,"Browse library","gift",()->presets(),"Import pack","save",()->{try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");activity.startActivityForResult(i,IMPORT);}catch(Exception e){error(e);}});
  if(workspace!=null)button("Continue editing",()->edit());
  button("Create a personal pack",()->{try{workspace=new PackWorkspace42(PresetPacks42.make(60));personalCopy();edit();}catch(Exception e){error(e);}});
  label("Saved on this device",20);File[] files=directory().listFiles();int count=0;
  if(files!=null){Arrays.sort(files);for(final File f:files)if(f.getName().endsWith(".json")&&!f.getName().equals("active.json"))try{final PackFormat.Pack x=PackFormat.parse(read(f));button(x.name()+" · "+x.count()+" names",()->preview(x,-1));count++;}catch(Exception e){label(f.getName()+" · could not load",14);}}
  if(count==0)label("Your imported and personal packs will appear here.",14);
  button("Restore original names",()->new AlertDialog.Builder(activity).setTitle("Restore original names?").setMessage("Your saved packs will remain available.").setPositiveButton("Restore",(d,w)->{try{if(active().exists()&&!active().delete())throw new IOException("Could not restore names.");new File(directory(),"active.json").delete();show();}catch(Exception e){error(e);}}).setNegativeButton("Cancel",null).show());
  button("About name packs",()->new AlertDialog.Builder(activity).setTitle("Name packs").setMessage("Packs change team, league and cup names. IDs, rosters and results stay stable. Built-in themes are fictional. Reviewed imports require a valid signature; edited copies are personal packs.").setPositiveButton("OK",null).show());
  button("Back to launcher",()->{Intent i=new Intent(activity,StartupActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP);activity.startActivity(i);});
 }
 private void presets(){page("Preset library");EditText q=input(presetQuery,"Search themes");Spinner cat=select("Collection",Arrays.asList("All","Nature","Space","Fantasy","City & Retro","Sport & Style"));cat.setSelection(Arrays.asList("All","Nature","Space","Fantasy","City & Retro","Sport & Style").indexOf(category));CheckBox fav=check("Favorites only",favoritesOnly);button("Search / filter",()->{presetQuery=q.getText().toString();category=cat.getSelectedItem().toString();favoritesOnly=fav.isChecked();presets();});int count=0;for(int i=0;i<PresetPacks42.THEMES.length;i++){String[] t=PresetPacks42.THEMES[i];if(!category.equals("All")&&!category.equals(t[0])||!(t[1]+" "+t[2]).toLowerCase(Locale.ROOT).contains(presetQuery.toLowerCase(Locale.ROOT))||favoritesOnly&&!favorites.contains(String.valueOf(i)))continue;final int n=i;count++;themeButton((favorites.contains(String.valueOf(i))?"★ ":"")+t[1]+"\n"+t[0],t[0],()->{try{preview(PresetPacks42.make(n),n);}catch(Exception e){error(e);}});}label(count+" of 75 themes",14);button("Back to packs",()->show());}
 private void preview(final PackFormat.Pack p,final int preset){page(p.name());label((preset>=0?"Built-in · fictional theme":p.reviewed?"Reviewed · signature verified":"Personal pack")+"\n"+p.count()+" names · "+p.data.get("author"),17);if(preset>=0)button(favorites.contains(String.valueOf(preset))?"★ Remove favorite":"☆ Add favorite",()->{String n=String.valueOf(preset);if(!favorites.remove(n))favorites.add(n);activity.getSharedPreferences("mayo_packs42",0).edit().putStringSet("favorites",new HashSet<>(favorites)).apply();preview(p,preset);});
  label("Before → After",23);int shown=0;for(String g:PackWorkspace42.GROUPS)for(Map.Entry<String,Object> e:p.names(g).entrySet())if(shown++<9)label(PackWorkspace42.original(g,e.getKey())+" → "+e.getValue(),14);label("Choose where to apply",23);Spinner sport=select("Sport",values("sport")),country=select("Country code",values("country"));CheckBox teams=check("Team names",true),leagues=check("League names",true),cups=check("Added cup names",true),merge=check("Merge with active names",false);
  button("Apply selected names",()->{try{Set<String> groups=new HashSet<>();if(teams.isChecked())groups.add("team_names");if(leagues.isChecked())groups.add("competition_names");if(cups.isChecked())groups.add("cup_names");if(groups.isEmpty())throw new IllegalArgumentException("Choose at least one name type.");String s=sport.getSelectedItem().toString(),c=country.getSelectedItem().toString();PackFormat.Pack chosen=s.equals("All")&&c.equals("All")&&groups.size()==3&&!merge.isChecked()?p:PackWorkspace42.scoped(p,currentActive(),groups,s,c,merge.isChecked());apply(chosen);show();}catch(Exception e){error(e);}});
  button("Customize this pack",()->{try{workspace=new PackWorkspace42(p);personalCopy();saveLocal();edit();}catch(Exception e){error(e);}});button("Export JSON",()->export(p.document,p.id()+".json"));if(preset<0)button("Delete saved pack",()->new AlertDialog.Builder(activity).setTitle("Delete "+p.name()+"?").setMessage("Applied names remain until you restore or replace them.").setPositiveButton("Delete",(d,w)->{File f=new File(directory(),p.id()+".json");if(f.exists()&&!f.delete())error(new IOException("Could not delete pack."));else show();}).setNegativeButton("Cancel",null).show());button(preset>=0?"Back to library":"Back to packs",()->{if(preset>=0)presets();else show();});
 }
 private List<String> values(String field){TreeSet<String>s=new TreeSet<>();for(String g:PackWorkspace42.GROUPS)for(String[]r:PackCatalog.rows(g))s.add(r[field.equals("sport")?2:3]);ArrayList<String>out=new ArrayList<>();out.add("All");out.addAll(s);return out;}
 private void apply(PackFormat.Pack p)throws Exception{File staging=new File(activity.getFilesDir(),"namepack-active.bin.new");PackFormat.binary(p,staging);if(!staging.renameTo(active()))throw new IOException("Could not activate pack.");write(new File(directory(),p.id()+".json"),p.document);write(new File(directory(),"active.json"),p.document);Toast.makeText(activity,"Names applied. Reopen game menus to refresh.",Toast.LENGTH_LONG).show();}
 private void personalCopy()throws Exception{Map<String,Object>m=PackWorkspace42.copy(workspace.pack().data);m.put("id","personal_"+Long.toHexString(System.currentTimeMillis()));m.put("author","Player");workspace=new PackWorkspace42(PackFormat.parse(PackFormat.stringify(m)));}
 private void saveLocal()throws Exception{PackFormat.Pack p=workspace.pack();write(new File(directory(),p.id()+".json"),p.document);}
 private void edit(){try{PackFormat.Pack p=workspace.pack();page("Customize names");label(p.count()+" custom names · changes save locally",15);EditText name=input(p.name(),"Pack title"),author=input((String)p.data.get("author"),"Author");button("Save title and author",()->{try{Map<String,Object>m=PackWorkspace42.copy(workspace.pack().data);m.put("name",name.getText().toString());m.put("author",author.getText().toString());workspace.commit(m);saveLocal();edit();}catch(Exception e){error(e);}});if(workspace.canUndo())button("Undo last change",()->{workspace.undo();try{saveLocal();edit();}catch(Exception e){error(e);}});if(workspace.canRedo())button("Redo change",()->{workspace.redo();try{saveLocal();edit();}catch(Exception e){error(e);}});for(String g:PackWorkspace42.GROUPS){final String key=g;button("Edit "+(g.equals("team_names")?"teams":g.equals("cup_names")?"cups":"leagues"),()->catalog(key,"","All","All",0));}button("Preview and apply",()->{try{preview(workspace.pack(),-1);}catch(Exception e){error(e);}});button("Duplicate pack",()->{try{personalCopy();saveLocal();edit();}catch(Exception e){error(e);}});button("Back to packs",()->show());}catch(Exception e){error(e);}}
 private void catalog(final String key,final String query,final String sport,final String country,final int offset){page(key.equals("team_names")?"Team names":key.equals("cup_names")?"Cup names":"League names");EditText q=input(query,"Search names or ID");Spinner sp=select("Sport",values("sport")),ct=select("Country",values("country"));sp.setSelection(values("sport").indexOf(sport));ct.setSelection(values("country").indexOf(country));button("Search / filter",()->catalog(key,q.getText().toString(),sp.getSelectedItem().toString(),ct.getSelectedItem().toString(),0));ArrayList<String[]>rows=new ArrayList<>();for(String[]r:PackCatalog.rows(key))if(PackWorkspace42.matches(r,sport,country,query))rows.add(r);label(rows.size()+" matches · page "+(offset/30+1),14);for(int i=offset;i<Math.min(offset+30,rows.size());i++){final String[]r=rows.get(i);String name=r[1];try{Object v=workspace.pack().names(key).get(r[0]);if(v!=null)name=(String)v;}catch(Exception e){error(e);}button(name+" · "+r[2]+" · "+r[3],()->rename(key,r,query,sport,country,offset));}if(offset>0)button("Previous 30",()->catalog(key,query,sport,country,Math.max(0,offset-30)));if(offset+30<rows.size())button("Next 30",()->catalog(key,query,sport,country,offset+30));if(!rows.isEmpty())button("Bulk edit "+rows.size()+" matches",()->bulk(key,query,sport,country,rows.size()));button("Back to editor",()->edit());}
 private void rename(String key,String[]r,String q,String sp,String ct,int off){try{EditText e=new EditText(activity);Object v=workspace.pack().names(key).get(r[0]);e.setSingleLine();e.setText(v==null?r[1]:(String)v);new AlertDialog.Builder(activity).setTitle(r[1]).setView(e).setPositiveButton("Save",(d,w)->{try{Map<String,Object>m=PackWorkspace42.copy(workspace.pack().data);PackFormat.object(m.get(key)).put(r[0],e.getText().toString());workspace.commit(m);saveLocal();catalog(key,q,sp,ct,off);}catch(Exception x){error(x);}}).setNeutralButton("Original",(d,w)->{try{Map<String,Object>m=PackWorkspace42.copy(workspace.pack().data);PackFormat.object(m.get(key)).remove(r[0]);workspace.commit(m);saveLocal();catalog(key,q,sp,ct,off);}catch(Exception x){error(x);}}).setNegativeButton("Cancel",null).show();}catch(Exception e){error(e);}}
 private void bulk(String key,String q,String sp,String ct,int n){page("Bulk edit");label(n+" matching names · "+sp+" · "+ct,17);EditText prefix=input("","Add prefix"),suffix=input("","Add suffix"),find=input("","Find text (optional)"),replace=input("","Replacement text");button("Save bulk change",()->{try{workspace.bulk(key,sp,ct,q,prefix.getText().toString(),suffix.getText().toString(),find.getText().toString(),replace.getText().toString(),false);saveLocal();catalog(key,q,sp,ct,0);}catch(Exception e){error(e);}});button("Restore matching original names",()->new AlertDialog.Builder(activity).setTitle("Restore "+n+" names?").setPositiveButton("Restore",(d,w)->{try{workspace.bulk(key,sp,ct,q,"","","","",true);saveLocal();catalog(key,q,sp,ct,0);}catch(Exception e){error(e);}}).setNegativeButton("Cancel",null).show());button("Back to results",()->catalog(key,q,sp,ct,0));}
 private void export(String document,String filename){exportDocument=document;try{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,filename);activity.startActivityForResult(i,EXPORT);}catch(Exception e){error(e);}}
 public boolean result(int request,int result,Intent data){if(request!=IMPORT&&request!=EXPORT)return false;if(result!=Activity.RESULT_OK||data==null||data.getData()==null)return true;try{Uri uri=data.getData();if(request==IMPORT){String text;try(InputStream in=activity.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Cannot open document.");text=PackFormat.utf8(PackFormat.read(in));}PackFormat.Pack p=PackFormat.parse(text);write(new File(directory(),p.id()+".json"),p.document);preview(p,-1);}else{if(exportDocument==null)throw new IOException("Export expired. Choose Export again.");try(OutputStream out=activity.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Cannot write document.");out.write(exportDocument.getBytes("UTF-8"));}Toast.makeText(activity,"Pack saved",Toast.LENGTH_LONG).show();}}catch(Exception e){error(e);}return true;}
}
